import json # Read only frozen validation-study results and exact checkpoint identities.
from pathlib import Path # Keep paired comparison evidence under the owned validation-study directory.
import numpy as np # Aggregate matched validation scores without accessing test or OOD fields.
import matplotlib # Render a reproducible scientific figure from actual logged measurements.
matplotlib.use('Agg') # Use a headless plotting backend without browser or generated imagery.
import matplotlib.pyplot as plt # Plot actual training checkpoints and physical-group validation errors.
import complex_operator as base # Reuse only the evidence root and deterministic JSON writer.
def run(): # Compare both seeds under identical initial data, initialization seeds and optimization budgets.
    directory=base.OUT/'friction_validation_variant';direct=json.loads((directory/'summary.json').read_text());incremental=json.loads((directory/'incremental_matched/summary.json').read_text());contract=json.loads((directory/'variant_contract.json').read_text());pairs=[] # Require both completed 200-epoch studies before computing comparisons.
    for seed in [17,41]: # Compare each random initialization against its matching counterpart.
        a=next(row for row in direct['members'] if row['seed']==seed);b=next(row for row in incremental['members'] if row['seed']==seed);pairs.append({'seed':seed,'incremental_validation_RMSE':b['validation_score'],'absolute_validation_RMSE':a['validation_score'],'relative_validation_improvement':(b['validation_score']-a['validation_score'])/b['validation_score'],'absolute_checkpoint':a['checkpoint'],'incremental_checkpoint':b['checkpoint']}) # Keep the actual per-seed effect rather than reporting only a favorable member.
    selected_direct=min(direct['members'],key=lambda row:row['validation_score']);selected_incremental=min(incremental['members'],key=lambda row:row['validation_score']);grouped={} # Apply the same validation-only selection rule to each architecture.
    for label,selected in [('absolute',selected_direct),('incremental',selected_incremental)]: # Use identical three complete validation histories for detailed physical-field diagnostics.
        rows=json.loads((base.resolve_path(selected['checkpoint']).parent/'validation/metrics.json').read_text())['cases'];names=sorted(set(group['group'] for row in rows for group in row['physical_groups']));grouped[label]={name:float(np.mean([group['relative_L2'] for row in rows for group in row['physical_groups'] if group['group']==name])) for name in names} # Keep physically commensurate groups and every validation case in the denominator.
    selected_improvement=(selected_incremental['validation_score']-selected_direct['validation_score'])/selected_incremental['validation_score'];summary={'status':'MATCHED_VALIDATION_ARCHITECTURE_COMPARISON_COMPLETE','training_histories':len(contract['training_ids']),'validation_histories':len(contract['validation_ids']),'epochs_per_seed_per_architecture':200,'seeds':[17,41],'paired_results':pairs,'selected_incremental_seed':selected_incremental['seed'],'selected_absolute_seed':selected_direct['seed'],'selected_validation_relative_improvement':selected_improvement,'physical_group_validation_errors':grouped,'same_initial_native_data':True,'same_initialization_seeds':True,'same_parameter_count':True,'same_optimizer_curriculum_and_update_budgets':all(incremental['training_AST_equal_to_direct_study'].values()),'test_or_ood_fields_opened':False,'selection_rule':'minimum complete cold-rollout normalized validation field RMSE','interpretation':'Validation evidence for choosing an output parametrization; no independent test, engineering, or full-equilibrium claim.'};base.write(directory/'comparison.json',summary) # Preserve the exact basis for architecture selection without extrapolating it to unseen histories.
    plt.rcParams.update({'font.size':10,'axes.spines.top':False,'axes.spines.right':False,'savefig.facecolor':'white'});figure,axes=plt.subplots(1,2,figsize=(12.8,4.4),gridspec_kw={'width_ratios':[1.1,1.]});colors={'absolute':'#167a9e','incremental':'#b24f24'} # Use a restrained reproducible scientific comparison layout.
    for architecture,folder in [('absolute',directory),('incremental',directory/'incremental_matched')]: # Draw only actually recorded validation checkpoints.
        for seed,style in [(17,'-'),(41,'--')]: # Preserve seed identity with line style rather than averaging histories.
            history=json.loads((folder/f'seed_{seed}/history.json').read_text())['history'];axes[0].plot([row['epoch'] for row in history],[row['validation_cold_rollout_normalized_RMSE'] for row in history],style,color=colors[architecture],marker='o',markersize=3,label=f'{architecture}, seed {seed}') # Show measured convergence rather than a synthetic smoothing curve.
    axes[0].set(xlabel='Optimization epoch',ylabel='Cold-rollout validation normalized RMSE',title='Same 200-epoch budget, full FE/IP fields');axes[0].grid(alpha=.18);axes[0].legend(fontsize=8) # State the actual experimental denominator and prediction mode.
    names=sorted(grouped['absolute']);positions=np.arange(len(names));width=.36 # Preserve the same physical-group order for both architectures.
    for offset,label in [(-width/2,'incremental'),(width/2,'absolute')]: axes[1].bar(positions+offset,[grouped[label][name] for name in names],width,color=colors[label],label=label) # Compare raw neural-to-native field mismatches for the selected validation members.
    axes[1].set_xticks(positions,[name.replace('_','\n') for name in names],fontsize=8);axes[1].set(ylabel='Mean relative L2 on 3 validation histories',title='Physical groups; prescribed entries excluded');axes[1].legend(fontsize=8);axes[1].grid(axis='y',alpha=.18);figure.suptitle('Validation-only output-head study — 8 training histories, 3 validation histories',fontsize=12);figure.tight_layout();figure.savefig(directory/'validation_architecture_comparison.png',dpi=180);figure.savefig(directory/'validation_architecture_comparison.svg');plt.close(figure) # Save portable data-backed scientific artifacts without involving independent final tests.
    print(json.dumps(summary,indent=2),flush=True) # Return concise verifiable architecture-selection evidence to the parent agent.
if __name__=='__main__': run() # Run only after both matched validation studies have completed.
